import csv, json, hashlib, re, sys
from pathlib import Path
from collections import defaultdict
from datetime import date
out=Path(__file__).resolve().parent; root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else out/'inputs'
source=json.loads((root/'source-data.json').read_text()); layouts=json.loads((root/'report-layouts.json').read_text())
for path,digest in source['source_sha256'].items():
    assert hashlib.sha256((root/path).read_bytes()).hexdigest()==digest, path
index=json.loads((root/'sources/editorial/source-index.json').read_text()); latest={}
for entry in index:
    if entry['published_on']<=source['cutoff'] and (entry['reference'] not in latest or entry['revision']>latest[entry['reference']]['revision']): latest[entry['reference']]=entry
rows=[]; provenance=[]
with (root/'sources/editorial/commitments.csv').open(newline='') as f:
    for c in csv.DictReader(f):
        ref=c['commitment']; entry=latest[ref]; data=(root/entry['path']).read_bytes(); text=data.decode(); match=re.search(r'^Completed: (.+)$',text,re.M); assert match
        value=match.group(1).strip(); completed=0 if value=='pending' else date.fromisoformat(value).day
        receipt_path=root/f'sources/editorial/{ref}-receipt.json'; receipt=json.loads(receipt_path.read_text()) if receipt_path.exists() else {}
        evidence=int(receipt.get('reference')==ref and receipt.get('source')==entry['path'] and receipt.get('sha256')==hashlib.sha256(data).hexdigest())
        row={'account':source['account'],'source_revision':source['revision'],'commitment':ref,'project':c['project'],'due_day':date.fromisoformat(c['due_on']).day,'completed_day':completed,'evidence':evidence}
        rows.append(row); provenance.append({'commitment':ref,'latest':entry,'sha256':hashlib.sha256(data).hexdigest(),'receipt':receipt or None,'evidence':evidence})
groups=defaultdict(list)
for row in rows: groups[row['project']].append(row)
summary=[]; recon=[]
for project,rs in sorted(groups.items()):
    base={'account':source['account'],'source_revision':source['revision'],'project':project}
    summary.append(dict(base,commitments=len(rs),completed=sum(r['completed_day']>0 for r in rs),on_time=sum(0<r['completed_day']<=r['due_day'] for r in rs)))
    available=sum(r['evidence'] for r in rs); recon.append(dict(base,required_references=len(rs),available_references=available,missing_references=len(rs)-available))
reports={'summary':summary,'detail':rows,'exceptions':[r for r in rows if not r['completed_day'] or r['completed_day']>r['due_day'] or not r['evidence']],'reconciliation':recon}
for name,contents in reports.items():
    with (out/f'{name}.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=layouts[name],lineterminator='\n'); w.writeheader(); w.writerows(contents)
(out/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
print(json.dumps({name:len(contents) for name,contents in reports.items()}))
